/bin/bash -c "python - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png')
# crop samples median and edge line profiles
# find pillow outlines via color deviations from smooth background: vertical/horizontal gradient
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY).astype(float)
gx=cv2.Sobel(g,cv2.CV_64F,1,0,ksize=3); gy=cv2.Sobel(g,cv2.CV_64F,0,1,ksize=3)
mag=np.hypot(gx,gy)
# top peaks per selected rows / cols
for y in [480,500,520,540,560,580,600,620,640,660,680,700]:
 xs=np.where(mag[y]>30)[0]
 # runs
 runs=[]
 for x in xs:
  if not runs or x>runs[-1][-1]+1:runs.append([x])
  else:runs[-1].append(x)
 print('row',y,[(r[0],r[-1]) for r in runs if len(r)>1][:30])
for x in [500,550,600,650,700,750,800,850,900,950,1000,1050]:
 ys=np.where(mag[:,x]>30)[0]
 runs=[]
 for y in ys:
  if not runs or y>runs[-1][-1]+1:runs.append([y])
  else:runs[-1].append(y)
 print('col',x,[(r[0],r[-1]) for r in runs if len(r)>1][:20])
PY"
